package org.apache.commons.math.stat.descriptive.moment;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.AbstractStorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.WeightedEvaluation;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.NullArgumentException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for Variance.copy(Variance source, Variance dest)
 */
public class Variance_copy_TriageGen0Test {

    @Test
    public void testCopy_Success() {
        // Arrange
        Variance source = new Variance(true);
        source.increment(1.0);
        source.increment(2.0);
        source.increment(3.0);

        double expectedResult = source.getResult();
        long expectedN = source.getN();
        boolean expectedBiasCorrected = source.isBiasCorrected();

        Variance dest = new Variance();

        // Act
        Variance.copy(source, dest);

        // Assert
        Assert.assertEquals("Result (variance) should be copied", expectedResult, dest.getResult(), 1e-10);
        Assert.assertEquals("N (count) should be copied", expectedN, dest.getN());
        Assert.assertEquals("Bias corrected flag should be copied", expectedBiasCorrected, dest.isBiasCorrected());
    }

    @Test
    public void testCopy_WithDifferentInitialState() {
        // Arrange
        Variance source = new Variance(false);
        source.increment(10.0);
        source.increment(20.0);

        Variance dest = new Variance(true); // Dest starts with different bias setting

        // Act
        Variance.copy(source, dest);

        // Assert
        Assert.assertEquals("Result should match source", source.getResult(), dest.getResult(), 1e-10);
        Assert.assertEquals("Bias corrected should match source (overwriting dest)", source.isBiasCorrected(), dest.isBiasCorrected());
    }

    @Test(expected = NullArgumentException.class)
    public void testCopy_SourceNull() {
        // Arrange
        Variance dest = new Variance();

        // Act
        Variance.copy(null, dest);
    }

    @Test(expected = NullArgumentException.class)
    public void testCopy_DestNull() {
        // Arrange
        Variance source = new Variance();

        // Act
        Variance.copy(source, null);
    }

    @Test(expected = NullArgumentException.class)
    public void testCopy_BothNull() {
        // Act
        Variance.copy(null, null);
    }
}
